//! Tray / window icon: a 270° gauge arc with a needle. The PNGs in `assets/` are generated by
//! `render` (run `RTM_REGEN_ICONS=1 cargo test -p rtm-sender --features gui icon` after changing
//! the drawing) and embedded, so the binary does not redraw them at startup. The same command
//! regenerates `assets/icon.ico`, the Windows exe icon that build.rs embeds.

use image::{Rgba, RgbaImage};

const PNG_32: &[u8] = include_bytes!("../../assets/icon-32.png");
const PNG_64: &[u8] = include_bytes!("../../assets/icon-64.png");
const PNG_32_PAUSED: &[u8] = include_bytes!("../../assets/icon-32-paused.png");
const PNG_64_PAUSED: &[u8] = include_bytes!("../../assets/icon-64-paused.png");

/// Shipped (size, paused, file name, bytes).
pub const ASSETS: [(u32, bool, &str, &[u8]); 4] = [
    (32, false, "icon-32.png", PNG_32),
    (64, false, "icon-64.png", PNG_64),
    (32, true, "icon-32-paused.png", PNG_32_PAUSED),
    (64, true, "icon-64-paused.png", PNG_64_PAUSED),
];

/// Decoded RGBA8 pixels of an embedded icon. Sizes other than 32/64 fall back to 64.
pub fn rgba(size: u32, paused: bool) -> (Vec<u8>, u32, u32) {
    let bytes = ASSETS
        .iter()
        .find(|a| a.0 == size && a.1 == paused)
        .or_else(|| ASSETS.iter().find(|a| a.0 == 64 && a.1 == paused))
        .map(|a| a.3)
        .unwrap_or(PNG_64);
    match image::load_from_memory_with_format(bytes, image::ImageFormat::Png) {
        Ok(img) => {
            let img = img.to_rgba8();
            let (w, h) = img.dimensions();
            (img.into_raw(), w, h)
        }
        // Cannot happen with the embedded files (a test decodes them); draw instead of failing.
        Err(_) => {
            let img = render(size, paused);
            (img.into_raw(), size, size)
        }
    }
}

/// Fraction of the arc shown as "filled", fixed (the icon is a glyph, not a live gauge).
const VALUE: f32 = 0.62;
const START_DEG: f32 = 225.0;
const SWEEP_DEG: f32 = 270.0;

/// Draw the glyph at `size`×`size` with 4×4 supersampling.
pub fn render(size: u32, paused: bool) -> RgbaImage {
    let (track, fill, needle, alpha) = if paused {
        ([110, 110, 115], [140, 140, 145], [170, 170, 175], 0.55)
    } else {
        ([80, 84, 96], [56, 200, 140], [240, 240, 240], 1.0)
    };
    const SS: u32 = 4;
    let mut img = RgbaImage::new(size, size);
    let value_deg = START_DEG - VALUE * SWEEP_DEG;
    let (vs, vc) = value_deg.to_radians().sin_cos();
    let tip = (0.5 + 0.34 * vc, 0.5 - 0.34 * vs);
    for py in 0..size {
        for px in 0..size {
            let mut acc = [0f32; 4]; // premultiplied rgb + alpha
            for sy in 0..SS {
                for sx in 0..SS {
                    let x = (px as f32 + (sx as f32 + 0.5) / SS as f32) / size as f32;
                    let y = (py as f32 + (sy as f32 + 0.5) / SS as f32) / size as f32;
                    if let Some(c) = shade(x, y, tip, track, fill, needle) {
                        for i in 0..3 {
                            acc[i] += c[i] as f32;
                        }
                        acc[3] += 1.0;
                    }
                }
            }
            let n = (SS * SS) as f32;
            let a = acc[3] / n;
            if a > 0.0 {
                let px_rgb = |i: usize| (acc[i] / acc[3]).round().clamp(0.0, 255.0) as u8;
                img.put_pixel(
                    px,
                    py,
                    Rgba([
                        px_rgb(0),
                        px_rgb(1),
                        px_rgb(2),
                        (a * alpha * 255.0).round() as u8,
                    ]),
                );
            }
        }
    }
    img
}

/// Colour of the topmost shape at unit coordinates (x, y), y pointing down.
fn shade(
    x: f32,
    y: f32,
    tip: (f32, f32),
    track: [u8; 3],
    fill: [u8; 3],
    needle: [u8; 3],
) -> Option<[u8; 3]> {
    let (dx, dy) = (x - 0.5, 0.5 - y);
    let r = (dx * dx + dy * dy).sqrt();
    // Hub and needle on top.
    if r <= 0.09 || dist_to_segment((x, y), (0.5, 0.5), tip) <= 0.035 {
        return Some(needle);
    }
    if (0.33..=0.47).contains(&r) {
        let theta = dy.atan2(dx).to_degrees();
        let from_start = (START_DEG - theta).rem_euclid(360.0);
        if from_start <= SWEEP_DEG * VALUE {
            return Some(fill);
        }
        if from_start <= SWEEP_DEG {
            return Some(track);
        }
    }
    None
}

fn dist_to_segment(p: (f32, f32), a: (f32, f32), b: (f32, f32)) -> f32 {
    let (abx, aby) = (b.0 - a.0, b.1 - a.1);
    let t = (((p.0 - a.0) * abx + (p.1 - a.1) * aby) / (abx * abx + aby * aby)).clamp(0.0, 1.0);
    let (cx, cy) = (a.0 + t * abx - p.0, a.1 + t * aby - p.1);
    (cx * cx + cy * cy).sqrt()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_icons_match_renderer() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets");
        let regen = std::env::var_os("RTM_REGEN_ICONS").is_some();
        for (size, paused, name, bytes) in ASSETS {
            let want = render(size, paused);
            if regen {
                want.save(dir.join(name)).unwrap();
                continue;
            }
            let got = image::load_from_memory(bytes).unwrap().to_rgba8();
            assert_eq!(got.dimensions(), (size, size), "{name}");
            assert!(
                got == want,
                "{name} is stale; regenerate with RTM_REGEN_ICONS=1"
            );
        }
    }

    /// Sizes in `assets/icon.ico` (the Windows exe icon, embedded by build.rs).
    const ICO_SIZES: [u32; 6] = [16, 24, 32, 48, 64, 256];

    /// An .ico whose entries are PNG images (supported by Windows Vista and later).
    fn ico_bytes() -> Vec<u8> {
        let pngs: Vec<Vec<u8>> = ICO_SIZES
            .iter()
            .map(|&s| {
                let mut buf = std::io::Cursor::new(Vec::new());
                render(s, false)
                    .write_to(&mut buf, image::ImageFormat::Png)
                    .unwrap();
                buf.into_inner()
            })
            .collect();
        let mut out = Vec::new();
        out.extend_from_slice(&[0, 0, 1, 0]); // reserved, type 1 = icon
        out.extend_from_slice(&(pngs.len() as u16).to_le_bytes());
        let mut offset = 6 + 16 * pngs.len() as u32;
        for (&size, png) in ICO_SIZES.iter().zip(&pngs) {
            let dim = if size >= 256 { 0 } else { size as u8 }; // 0 means 256
            out.extend_from_slice(&[dim, dim, 0, 0]); // w, h, palette, reserved
            out.extend_from_slice(&1u16.to_le_bytes()); // planes
            out.extend_from_slice(&32u16.to_le_bytes()); // bits per pixel
            out.extend_from_slice(&(png.len() as u32).to_le_bytes());
            out.extend_from_slice(&offset.to_le_bytes());
            offset += png.len() as u32;
        }
        for png in &pngs {
            out.extend_from_slice(png);
        }
        out
    }

    /// Entries of an .ico made of PNGs: (size, decoded image).
    fn parse_ico(b: &[u8]) -> Vec<(u32, RgbaImage)> {
        let u16_at = |i: usize| u16::from_le_bytes([b[i], b[i + 1]]);
        let u32_at = |i: usize| u32::from_le_bytes([b[i], b[i + 1], b[i + 2], b[i + 3]]);
        assert_eq!((u16_at(0), u16_at(2)), (0, 1), "not an icon file");
        (0..u16_at(4) as usize)
            .map(|n| {
                let e = 6 + 16 * n;
                let size = if b[e] == 0 { 256 } else { u32::from(b[e]) };
                let (len, off) = (u32_at(e + 8) as usize, u32_at(e + 12) as usize);
                let img = image::load_from_memory_with_format(
                    &b[off..off + len],
                    image::ImageFormat::Png,
                )
                .unwrap()
                .to_rgba8();
                (size, img)
            })
            .collect()
    }

    #[test]
    fn exe_icon_matches_renderer() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("assets/icon.ico");
        if std::env::var_os("RTM_REGEN_ICONS").is_some() {
            std::fs::write(&path, ico_bytes()).unwrap();
        }
        let got = parse_ico(&std::fs::read(&path).unwrap());
        assert_eq!(
            got.iter().map(|e| e.0).collect::<Vec<_>>(),
            ICO_SIZES,
            "icon.ico sizes"
        );
        for (size, img) in got {
            assert_eq!(img.dimensions(), (size, size));
            assert!(
                img == render(size, false),
                "icon.ico ({size} px) is stale; regenerate with RTM_REGEN_ICONS=1"
            );
        }
    }

    #[test]
    fn icon_shape_is_sane() {
        let img = render(64, false);
        // Transparent corners, opaque hub, gap at the bottom of the gauge.
        assert_eq!(img.get_pixel(0, 0)[3], 0);
        assert_eq!(img.get_pixel(32, 32)[3], 255);
        assert_eq!(img.get_pixel(32, 60)[3], 0);
        // Paused variant is dimmer.
        let p = render(64, true);
        assert!(p.get_pixel(32, 32)[3] < 255);
        let (rgba, w, h) = rgba(32, true);
        assert_eq!((rgba.len(), w, h), (32 * 32 * 4, 32, 32));
    }
}
